def choose_move(observation):
    w = observation['grid_width']
    h = observation['grid_height']
    my_x, my_y = observation['self_position']
    opp_x, opp_y = observation['opponent_position']
    obstacles = set(map(tuple, observation.get('obstacles', [])))
    resources = observation.get('resources', [])
    score_self, score_opp = observation.get('scores', [0,0])
    my_path = set(map(tuple, observation.get('self_path', [])))
    opp_path = set(map(tuple, observation.get('opponent_path', [])))
    def safe(x,y):
        return 0 <= x < w and 0 <= y < h and (x,y) not in obstacles
    moves = {'UP': (0,-1), 'DOWN': (0,1), 'LEFT': (-1,0), 'RIGHT': (1,0)}
    best_move = None
    best_score_diff = -float('inf')
    for dir_name, (dx,dy) in moves.items():
        nx, ny = my_x+dx, my_y+dy
        if not safe(nx, ny):
            continue
        if (nx, ny) in my_path:
            continue
        score_diff = score_self - score_opp
        for res in resources:
            if res['x']==nx and res['y']==ny:
                score_diff += 1
        if score_diff > best_score_diff:
            best_score_diff = score_diff
            best_move = (dx, dy)
    if best_move:
        return list(best_move)
    return [0,0]
